const raw = String($json.query?.certificate_code ?? '').trim();
const valid = /^VINE-[A-Z0-9-]{8,80}$/.test(raw);
return [{json:{certificate_code: valid ? raw : 'INVALID', input_valid: valid}}];

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeImage = (value) => /^https:\/\//i.test(String(value ?? '')) ? String(value) : '';
const found = $json.input_valid === true && ($json.found === true || String($json.found) === 'true');
const base = '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vine Certificate Service</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#102018;color:#f4f2e8;font:16px/1.55 Inter,system-ui,sans-serif}.wrap{max-width:820px;margin:auto;padding:28px 18px 56px}.brand{color:#b6d76a;text-transform:uppercase;letter-spacing:.12em;font-size:.78rem}.card{background:#1a3024;border:1px solid #34523c;border-radius:20px;overflow:hidden;box-shadow:0 20px 50px #0006}.hero{width:100%;max-height:320px;object-fit:cover;background:#28412f}.body{padding:26px}.pill{display:inline-block;padding:5px 12px;border-radius:99px;background:#315d3b;color:#e6f5bd;font-weight:700}.code{font-family:ui-monospace,monospace;color:#d4e89b;overflow-wrap:anywhere}.updates{display:grid;gap:14px;margin-top:18px}.update{padding:16px;border:1px solid #36533d;border-radius:14px;background:#14271c}.update img{width:100%;max-height:220px;object-fit:cover;border-radius:10px;margin-top:12px}.muted{color:#bbcabd}.notfound{text-align:center;padding:64px 24px}@media(max-width:560px){.wrap{padding:14px}.body{padding:20px}}</style></head><body><main class="wrap"><div class="brand">Vine Certificate Service</div>';
let html, status;
if (!found) {
 status=404; html=base+'<section class="card notfound"><h1>Сертификат не найден</h1><p class="muted">Проверьте код сертификата и повторите попытку.</p></section></main></body></html>';
} else {
 status=200; const v=JSON.parse($json.vine_json); const photo=safeImage(v.photo_link); const updates=(v.updates||[]).map(u=>'<article class="update"><strong>'+esc(u.date)+'</strong><p>'+esc(u.update_text)+'</p>'+(safeImage(u.photo_link)?'<img src="'+esc(safeImage(u.photo_link))+'" alt="Фото обновления лозы">':'')+'</article>').join('') || '<p class="muted">Обновлений пока нет.</p>';
 html=base+'<section class="card">'+(photo?'<img class="hero" src="'+esc(photo)+'" alt="Именная виноградная лоза">':'')+'<div class="body"><span class="pill">'+esc(v.status)+'</span><h1>'+esc(v.vine_name)+'</h1><p>Владелец: <strong>'+esc(v.owner_name)+'</strong></p><p class="code">'+esc(v.certificate_code)+'</p><p class="muted">Последнее обновление: '+esc(v.last_update)+'</p><h2>История лозы</h2><div class="updates">'+updates+'</div></div></section></main></body></html>';
}
return [{json:{html,http_status:status}}];
